"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["87824"],{11323(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_candidato.nao_encontrado","status":404,"titulo":"Fato do candidato n\xe3o encontrado"},"descricao":{"codigo":"uniplus.configuracao.fato_candidato.nao_encontrado","requisitos":[],"oQueAconteceu":["O `{id}` da rota, ou o `itemId` do corpo nas opera\xe7\xf5es da prote\xe7\xe3o de dados, n\xe3o corresponde a nenhum fato do cat\xe1logo. A recusa vale para as opera\xe7\xf5es que alteram um fato existente: o nome, a descri\xe7\xe3o e a forma de exibi\xe7\xe3o (`PUT /api/configuracao/admin/fatos-candidato/{id}`), a defini\xe7\xe3o (`PUT /api/configuracao/admin/fatos-candidato/{id}/definicao`), as regras padr\xe3o (`PUT /api/configuracao/admin/fatos-candidato/{id}/regras-padrao`), a desativa\xe7\xe3o (`DELETE /api/configuracao/admin/fatos-candidato/{id}`) e a reativa\xe7\xe3o (`POST /api/configuracao/admin/fatos-candidato/{id}/ativacao`), os valores (`POST /api/configuracao/admin/fatos-candidato/{id}/valores`, `PUT /api/configuracao/admin/fatos-candidato/{id}/valores/{codigo}`, `PUT /api/configuracao/admin/fatos-candidato/{id}/ordem-dos-valores`, `DELETE /api/configuracao/admin/fatos-candidato/{id}/valores/{codigo}` e `POST /api/configuracao/admin/fatos-candidato/{id}/valores/{codigo}/ativacao`), o aceite da recomenda\xe7\xe3o de ajuste da prote\xe7\xe3o de dados (`POST /api/configuracao/admin/fatos-candidato/{id}/aceite-da-recomendacao`) e, para um item do cadastro de fatos, a decis\xe3o (`POST /api/configuracao/admin/protecao-do-catalogo`) e a manifesta\xe7\xe3o (`POST /api/configuracao/admin/protecao-do-catalogo/manifestacoes`) sobre a prote\xe7\xe3o de dados. O fato desativado continua no cat\xe1logo e n\xe3o gera esta resposta.","A busca do fato vem antes das demais confer\xeancias, e nas opera\xe7\xf5es de valor vem antes da busca do valor. A exce\xe7\xe3o \xe9 a defini\xe7\xe3o das regras padr\xe3o: as regras enviadas s\xe3o montadas primeiro, e qualquer falha nessa montagem, como uma regra ou condi\xe7\xe3o nula ([regra padr\xe3o malformada](/erros/uniplus.configuracao.fato_candidato.regra_padrao_malformada)), uma cl\xe1usula vazia ou um campo `contribui` em branco, \xe9 recusada antes de o fato ser procurado. A valida\xe7\xe3o do corpo na borda HTTP tamb\xe9m vem antes da busca. A resposta n\xe3o traz a lista `errors`."],"comoResolver":["Confira o identificador do fato. Para encontrar o fato certo, consulte a lista de manuten\xe7\xe3o (`GET /api/configuracao/admin/fatos-candidato`), que traz os fatos ativos e os desativados, e use o `id` de l\xe1. Se o fato nunca foi cadastrado, cadastre-o (`POST /api/configuracao/admin/fatos-candidato`)."],"ondeAparece":["Altera\xe7\xe3o de um fato do cat\xe1logo","Altera\xe7\xe3o da defini\xe7\xe3o de um fato do cat\xe1logo","Defini\xe7\xe3o das regras padr\xe3o de um fato derivado por regra","Desativa\xe7\xe3o de um fato do cat\xe1logo","Reativa\xe7\xe3o de um fato do cat\xe1logo","Acr\xe9scimo de um valor a um fato do cat\xe1logo","Corre\xe7\xe3o de um valor de um fato do cat\xe1logo","Reordena\xe7\xe3o dos valores de um fato do cat\xe1logo","Desativa\xe7\xe3o de um valor de um fato do cat\xe1logo","Reativa\xe7\xe3o de um valor de um fato do cat\xe1logo","Aceite da recomenda\xe7\xe3o de ajuste da prote\xe7\xe3o de dados de um fato do cat\xe1logo","Decis\xe3o sobre a prote\xe7\xe3o de dados de um fato do cat\xe1logo","Manifesta\xe7\xe3o sobre a prote\xe7\xe3o de dados de um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato candidato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);